type WatcherDispatchSource = 'scheduled' | 'manual' | 'event';

export interface WatcherRunPayload {
  watcher_id: number;
  agent_id: string;
  window_start: string;
  window_end: string;
  dispatch_source: WatcherDispatchSource;
  /**
   * Snapshot of the watcher's `current_version_id` at run-creation time.
   * The agent and `complete_window` use this fixed version for the entire
   * extraction lifecycle so a mid-run group edit cannot validate v1's output
   * against v2's schema.
   */
  version_id: number | null;
  /**
   * When non-null, the watcher is pinned to a user-owned device worker.
   * The server-side dispatcher (`packages/server/src/watchers/automation.ts`)
   * MUST refuse to claim such rows — they are claimed exclusively by the
   * matching device worker via `/api/workers/poll`. Mirrors the
   * `connections.device_worker_id` lane that the worker poll already
   * supports for sync runs.
   */
  device_worker_id?: string | null;
  /**
   * Hint to the device-side dispatcher (Owletto Mac app, etc.) for which
   * local CLI executor to spawn (e.g. `claude-code`, `codex`, `gemini`).
   * Free-form string. Empty / null means "use the device's configured
   * default agent".
   */
  agent_kind?: string | null;
  /** Present for connector-event activations; raw webhook bodies never enter a run. */
  trigger_signal?: ConnectorTriggerSignal;
  /** Coalesced deliveries waiting in this run, including trigger_signal. */
  trigger_signals?: ConnectorTriggerSignal[];
  delivery_ids?: string[];
  trigger_execution?: 'turn' | 'window';
  trigger_output?: 'silent' | 'reply_to_source';
  trigger_key?: string;
  source_fingerprint?: string;
}

function behaviorEventTriggerKey(trigger: BehaviorEventTrigger): string {
  return stableJson({
    kind: 'event',
    connector_key: trigger.connector_key,
    connection_id: trigger.connection_id ?? null,
    event_types: [...trigger.event_types].sort(),
    match: trigger.match ?? null,
    execution: trigger.execution ?? 'turn',
    active_run: trigger.active_run ?? 'queue',
    output: trigger.output ?? 'silent',
    skip_if_unchanged: trigger.skip_if_unchanged ?? true,
  });
}

const WATCHER_EXECUTION_UNIQUE_INDEX = 'idx_runs_executing_per_behavior';

/**
 * Claim one pending Behavior run while holding the durable per-Behavior row
 * lock. Both the server dispatcher and device poller use this transition so
 * replicas cannot promote different queued runs from the same Behavior at the
 * same time.
 */
export async function claimPendingWatcherRun(
  tx: DbClient,
  params: {
    runId: number;
    watcherId: number;
    claimedBy: string;
    status: 'claimed' | 'running';
  }
): Promise<boolean> {
  const watcher = await tx`
    SELECT id
    FROM watchers
    WHERE id = ${params.watcherId}
    FOR UPDATE SKIP LOCKED
  `;
  if (watcher.length === 0) return false;

  try {
    const claimed = await tx.savepoint(
      async (sp) => sp`
        UPDATE runs r
        SET status = ${params.status},
            claimed_at = current_timestamp,
            last_heartbeat_at = CASE
              WHEN ${params.status}::text = 'running' THEN current_timestamp
              ELSE r.last_heartbeat_at
            END,
            claimed_by = ${params.claimedBy}
        WHERE r.id = ${params.runId}
          AND r.watcher_id = ${params.watcherId}
          AND r.run_type = 'behavior'
          AND r.status = 'pending'
          AND NOT EXISTS (
            SELECT 1
            FROM runs active
            WHERE active.watcher_id = r.watcher_id
              AND active.run_type = 'behavior'
              AND active.status IN ('claimed', 'running')
          )
        RETURNING r.id
      `
    );
    return claimed.length > 0;
  } catch (error) {
    // During a rolling deployment an older replica may still claim without
    // taking the watcher row lock. The unique index remains authoritative;
    // contain that expected contention inside the savepoint and skip the run.
    if (isUniqueViolation(error, WATCHER_EXECUTION_UNIQUE_INDEX)) return false;
    throw error;
  }
}

// ============================================
// Run Management
// ============================================

/**
 * A feed whose connector can't be resolved to runnable code is an orphan: the
 * connector was archived/uninstalled, or its version was registered without
 * compiled code and has no bundled source to compile on demand. Soft-delete it
 * in-place so it stops appearing in CheckDueFeeds — a warn + return null would
 * repeat at the same cadence forever (~1/min), and a large enough orphan set
 * fills the CheckDueFeeds LIMIT 100 and starves legitimate feeds. Operators
 * recover by registering connector code and clearing `deleted_at`.
 */
async function softDeleteOrphanFeed(
  sql: DbClient,
  feedId: number,
  feed: { connector_key: string; organization_id: string },
  reason: string
): Promise<void> {
  await sql`
    UPDATE feeds
    SET deleted_at = current_timestamp
    WHERE id = ${feedId}
  `;
  logger.warn(
    { feedId, connector_key: feed.connector_key, organization_id: feed.organization_id },
    `[queue] Soft-deleted orphan feed — ${reason}`
  );
}

/**
 * Resolve the active connector version (pinned_version → newest active
 * connector_definition) and, when `requireRunnable`, verify the
 * connector_versions row has compiled_code OR a bundled source file on disk.
 * Returns a discriminated result so each caller maps the failure modes to its
 * own behavior (sync soft-deletes the orphan feed; auth/action throw).
 */
type ConnectorVersionResolution =
  | { ok: true; version: string; compiledCode: string | null; sourcePath: string | null }
  | { ok: false; reason: 'no-definition' }
  | { ok: false; reason: 'no-version'; version: string }
  | { ok: false; reason: 'not-runnable'; version: string };

async function resolveActiveConnectorVersion(
  sql: DbClient,
  params: {
    orgId: string;
    connectorKey: string;
    requireRunnable: boolean;
    pinnedVersion?: string | null;
  }
): Promise<ConnectorVersionResolution> {
  let version: string;
  if (params.pinnedVersion) {
    version = params.pinnedVersion;
  } else {
    const defRows = await sql`
      SELECT version FROM connector_definitions
      WHERE key = ${params.connectorKey}
        AND organization_id = ${params.orgId}
        AND status = 'active'
      ORDER BY updated_at DESC, id DESC
      LIMIT 1
    `;
    if (defRows.length === 0) {
      return { ok: false, reason: 'no-definition' };
    }
    version = (defRows[0] as { version: string }).version;
  }

  if (!params.requireRunnable) {
    return { ok: true, version, compiledCode: null, sourcePath: null };
  }

  const versionRows = await sql`
    SELECT compiled_code, source_path FROM connector_versions
    WHERE connector_key = ${params.connectorKey} AND version = ${version}
      AND (organization_id = ${params.orgId} OR organization_id IS NULL)
    ORDER BY organization_id NULLS LAST
    LIMIT 1
  `;
  if (versionRows.length === 0) {
    return { ok: false, reason: 'no-version', version };
  }
  const { compiled_code, source_path } = versionRows[0] as {
    compiled_code: string | null;
    source_path: string | null;
  };
  // Runnable if ANY runtime code source exists: stored compiled code, a
  // source_path the runtime can compile on demand, or a bundled connector
  // file. Union of all three so no run type (sync/auth/operation) regresses —
  // resolveConnectorCode() resolves from whichever is present at execution.
  if (
    !compiled_code &&
    !source_path &&
    !findBundledConnectorFile(params.connectorKey)
  ) {
    return { ok: false, reason: 'not-runnable', version };
  }
  return { ok: true, version, compiledCode: compiled_code, sourcePath: source_path };
}

/**
 * Why no sync run was queued. The reasons differ in remedy — `already_active`
 * resolves itself when the current run finishes, while the others never will
 * (the two connector reasons also retire the feed) — so callers that surface
 * a skip to a human must render the specific reason, not a catch-all.
 */
export type SyncRunSkipReason =
  | 'already_active'
  | 'feed_not_found'
  | 'cloud_restricted'
  | 'connector_uninstalled'
  | 'connector_version_unrunnable';

export type CreateSyncRunResult =
  | { ok: true; runId: number }
  | { ok: false; reason: SyncRunSkipReason };

/** Operator-facing sentence per cause. Kept beside the reasons so a new reason
 *  cannot be added without deciding what a human should be told. */
export function describeSyncRunSkip(reason: SyncRunSkipReason): string {
  switch (reason) {
    case 'already_active':
      return 'Sync already pending or running for this feed';
    case 'feed_not_found':
      return 'Feed not found';
    case 'cloud_restricted':
      return 'This connector cannot run on Lobu Cloud yet, so no sync was queued';
    case 'connector_uninstalled':
      return 'The connector is no longer installed in this workspace; the feed has been retired';
    case 'connector_version_unrunnable':
      return 'The connector version has no runnable code; the feed has been retired';
  }
}

/**
 * Create a pending sync run for a feed (within an existing client/tx). Skips
 * with a `SyncRunSkipReason` instead of queueing when a run is already active,
 * the feed is missing or cloud-restricted, or the connector resolves to
 * nothing runnable — the connector cases also soft-delete the feed (see
 * softDeleteOrphanFeed).
 */
async function createSyncRunWithClient(
  sql: DbClient,
  feedId: number,
  dryRun = false
): Promise<CreateSyncRunResult> {
  // Check if there's already a pending/running run for this feed
  const existing = await sql`
    SELECT id FROM runs
    WHERE feed_id = ${feedId}
      AND run_type = 'sync'
      AND status = ANY(${runStatusLiteral(ACTIVE_RUN_STATUSES)}::text[])
    LIMIT 1
  `;

  if (existing.length > 0) {
    logger.info(
      `[queue] Skipping run creation for feed ${feedId} - already has pending/running run`
    );
    return { ok: false, reason: 'already_active' };
  }

  // Get feed details (including pinned_version)
  const feedRows = await sql`
    SELECT f.organization_id, f.connection_id, f.pinned_version, f.schedule, f.timezone,
           c.connector_key
    FROM feeds f
    JOIN connections c ON c.id = f.connection_id
    WHERE f.id = ${feedId}
  `;
  if (feedRows.length === 0) {
    logger.warn(`[queue] Feed ${feedId} not found`);
    return { ok: false, reason: 'feed_not_found' };
  }
  const feed = feedRows[0] as {
    organization_id: string;
    connection_id: number;
    connector_key: string;
    pinned_version: string | null;
    schedule: string | null;
    timezone: string | null;
  };

  // Cloud gate: a raw-DB connector (postgres) has no tenant-URL egress hardening
  // yet, so under LOBU_CLOUD_MODE we don't queue a scheduled sync run for it. The
  // connection is already blocked at create time, but an existing feed must not
  // keep queueing. The feed is left intact (NOT soft-deleted) — it's a valid feed
  // that simply can't run on cloud until hardening lands; self-hosted is
  // unaffected. pollWorkerJob gates again as the hard execution boundary.
  if (isCloudMode() && CLOUD_RESTRICTED_CONNECTOR_KEYS.has(feed.connector_key)) {
    logger.warn(
      { feedId, connector_key: feed.connector_key },
      '[queue] Skipping sync run for cloud-restricted connector under LOBU_CLOUD_MODE'
    );
    return { ok: false, reason: 'cloud_restricted' };
  }

  // Resolve connector version: pinned_version → connector_definitions.version,
  // then verify the version has compiled code or a bundled source for on-demand
  // compilation.
  const resolved = await resolveActiveConnectorVersion(sql, {
    orgId: feed.organization_id,
    connectorKey: feed.connector_key,
    requireRunnable: true,
    pinnedVersion: feed.pinned_version,
  });
  if (!resolved.ok) {
    if (resolved.reason === 'no-definition') {
      // The connector was archived/uninstalled in this org but the feed wasn't
      // soft-deleted (see softDeleteOrphanFeed for why we soft-delete rather
      // than warn-and-return).
      await softDeleteOrphanFeed(
        sql,
        feedId,
        feed,
        'no active connector_definition for (connector_key, org).'
      );
      return { ok: false, reason: 'connector_uninstalled' };
    }
    if (resolved.reason === 'no-version') {
      throw new Error(
        `No connector version '${resolved.version}' found for '${feed.connector_key}'. Build/register connector code first.`
      );
    }
    // not-runnable: version is registered but has neither persisted compiled
    // code nor a bundled source file to compile on demand (e.g. a connector key
    // like `chrome.tabs` that was never a standalone bundled connector). It can
    // never run — treat it as an orphan so it stops storming CheckDueFeeds with
    // a per-poll error instead of looping forever (#1012).
    await softDeleteOrphanFeed(
      sql,
      feedId,
      feed,
      `no compiled code and no bundled source for version '${resolved.version}'.`
    );
    return { ok: false, reason: 'connector_version_unrunnable' };
  }
  const connectorVersion = resolved.version;

  // Manual feeds (schedule null) keep next_run_at null after enqueue so they
  // are not re-picked by the due-feed scheduler.
  const nextRunAt = feed.schedule
    ? nextRunAtFromCron(feed.schedule, new Date(), feed.timezone)
    : null;
  // A dry run inserts the run row and stops there. The sibling `UPDATE feeds`
  // below is a real side effect — it stamps `last_sync_status = 'pending'`,
  // clears `last_error`, and rolls `next_run_at` forward to the next cron slot.
  // Letting a dry run do that would move the feed's schedule and overwrite the
  // recorded outcome of the last REAL sync, which is exactly the state a dry
  // run exists to leave untouched.
  const inserted = dryRun
    ? await sql`
    INSERT INTO runs (
      organization_id, run_type, feed_id, connection_id,
      connector_key, connector_version, status, approval_status, created_at,
      dry_run
    ) VALUES (
      ${feed.organization_id}, 'sync', ${feedId}, ${feed.connection_id},
      ${feed.connector_key}, ${connectorVersion}, 'pending', 'auto', current_timestamp,
      true
    )
    RETURNING id
  `
    : await sql`
    WITH inserted AS (
      INSERT INTO runs (
        organization_id, run_type, feed_id, connection_id,
        connector_key, connector_version, status, approval_status, created_at
      ) VALUES (
        ${feed.organization_id}, 'sync', ${feedId}, ${feed.connection_id},
        ${feed.connector_key}, ${connectorVersion}, 'pending', 'auto', current_timestamp
      )
      RETURNING id, feed_id
    )
	const prompt = rows[0]?.prompt;
	return typeof prompt === "string" ? prompt : undefined;
}

async function failWatcherRun(
	sql: DbClient,
	runId: number,
	message: string
): Promise<void> {
	await markWatcherRunFailedIdempotent(sql, runId, message);
}

async function claimWatcherRun(
	sql: DbClient,
	runId?: number
): Promise<ClaimedWatcherRunRow | null> {
	return sql.begin(async (tx) => {
		const specificRunClause = runId ? tx`AND r.id = ${runId}` : tx``;
		// Skip runs pinned to a device worker (#802): the user's Mac (or other
		// device) will claim these via /api/workers/poll. Without this filter the
		// server-side dispatcher races the device worker for the same row — the
		// exact failure mode that caused the watcher-run silent-success bug.
		// The pin currently lives in approved_input JSONB (issue #799 will add a
		// proper column); both shapes are guarded here so the filter survives
		// either schema.
		const candidates = await tx`
      SELECT r.id, r.organization_id, r.watcher_id, r.approved_input
      FROM runs r
      WHERE r.run_type = 'behavior'
        AND r.status = 'pending'
        AND NOT EXISTS (
          SELECT 1
          FROM runs active
          WHERE active.watcher_id = r.watcher_id
            AND active.run_type = 'behavior'
            AND active.status IN ('claimed', 'running')
        )
        AND (
          r.approved_input->>'device_worker_id' IS NULL
          OR r.approved_input->>'device_worker_id' = ''
        )
        ${specificRunClause}
      ORDER BY r.created_at ASC
      FOR UPDATE SKIP LOCKED
      LIMIT 1
    `;

		if (candidates.length === 0) return null;
		const candidate = candidates[0] as {
			id: unknown;
			organization_id: unknown;
			watcher_id: unknown;
			approved_input: unknown;
		};
		const candidateId = Number(candidate.id);
		const watcherId = Number(candidate.watcher_id);
		const claimed = await claimPendingWatcherRun(tx, {
			runId: candidateId,
			watcherId,
			claimedBy: "lobu-dispatcher",
			status: "claimed",
		});
		if (!claimed) return null;

		return {
			id: candidateId,
			organization_id: String(candidate.organization_id),
			watcher_id: watcherId,
			approved_input: candidate.approved_input,
		};
	});
}

/**
 * Read a watcher's optional per-watcher model override from
 * `watchers.execution_config.model` (a `provider/model` ref or "auto"). This is
 * the SAME field the device-worker lane already reads as the CLI `--model` flag
 * (BehaviorExecutionConfigSchema.model), so the server-side dispatch lane and the
 * device lane share one storage location. Returns undefined when unset so the
 * caller falls through to the agent/org default.
 */
async function getWatcherModelOverride(
	sql: DbClient,
	watcherId: number
): Promise<string | undefined> {
	const rows = await sql`
    SELECT execution_config->>'model' AS model
    FROM watchers
    WHERE id = ${watcherId}
    LIMIT 1
  `;
	const model = rows[0]?.model as string | null | undefined;
	return typeof model === "string" && model.trim() ? model.trim() : undefined;
}

async function ensureWatcherAgentExists(
	sql: DbClient,
	organizationId: string,
	agentId: string
): Promise<boolean> {
	const rows = await sql`

  try {
    if (db) {
      return await createSyncRunWithClient(sql, feedId, dryRun);
    }

    return await sql.begin(async (tx) =>
      createSyncRunWithClient(tx, feedId, dryRun)
    );
  } catch (error) {
    if (isUniqueViolation(error, 'idx_runs_active_sync_per_feed')) {
      logger.info(`[queue] Skipping run creation for feed ${feedId} - duplicate active sync run`);
      // Lost the race against a concurrent trigger — indistinguishable, from
      // here, from having found that run on the way in.
      return { ok: false, reason: 'already_active' };
    }
    logger.error({ error }, `[queue] Failed to create sync run for feed ${feedId}`);
    throw error;
  }
}

async function findActiveWatcherRun(
  sql: DbClient,
  watcherId: number
): Promise<{ id: number; status: string } | null> {
  const existing = await sql`
    SELECT id, status
    FROM runs
    WHERE watcher_id = ${watcherId}
      AND run_type = 'behavior'
      AND status = ANY(${runStatusLiteral(ACTIVE_RUN_STATUSES)}::text[])
    ORDER BY created_at ASC
    LIMIT 1
  `;

  if (existing.length === 0) return null;

  return {
    id: Number((existing[0] as { id: unknown }).id),
    status: String((existing[0] as { status: unknown }).status),
  };
}

async function createWatcherRunWithClient(
  sql: DbClient,
  params: {
    organizationId: string;
    watcherId: number;
    agentId: string;
    windowStart: string;
    windowEnd: string;
    dispatchSource: WatcherDispatchSource;
    deviceWorkerId?: string | null;
    agentKind?: string | null;
    sourceFingerprint?: string;
  }
): Promise<{ runId: number; status: string; created: boolean }> {
  const existing = await findActiveWatcherRun(sql, params.watcherId);
  if (existing) {
    logger.info(
      `[queue] Reusing active watcher run ${existing.id} for watcher ${params.watcherId}`
    );
    return { runId: existing.id, status: existing.status, created: false };
  }

  // Snapshot the watcher's current_version_id at run-creation time so the
  // entire run uses a fixed version even if the group is edited mid-run.
  const versionRows = await sql`
    SELECT current_version_id FROM watchers WHERE id = ${params.watcherId} LIMIT 1
  `;
  const snapshotVersionId =
    versionRows.length > 0 && versionRows[0].current_version_id != null
      ? Number(versionRows[0].current_version_id)
      : null;

  // device_worker_id + agent_kind get persisted into approved_input so the
  // server-side dispatcher (#802) can skip device-pinned rows from the SQL
  // side, and so /api/workers/poll can claim them with a parallel CTE
  // branch without a runs-schema migration. Empty strings are normalized to
  // null so the dispatcher's `OR '' = ''` guard treats them as un-pinned.
  const normalizedDeviceWorkerId =
    typeof params.deviceWorkerId === 'string' && params.deviceWorkerId.trim() !== ''
      ? params.deviceWorkerId.trim()
      : null;
  const normalizedAgentKind =
    typeof params.agentKind === 'string' && params.agentKind.trim() !== ''
      ? params.agentKind.trim()
      : null;

  const payload: WatcherRunPayload = {
    watcher_id: params.watcherId,
    agent_id: params.agentId,
    window_start: params.windowStart,
    window_end: params.windowEnd,
    dispatch_source: params.dispatchSource,
    version_id: snapshotVersionId,
    device_worker_id: normalizedDeviceWorkerId,
    agent_kind: normalizedAgentKind,
    source_fingerprint: params.sourceFingerprint,
  };
  const idempotencyKey = [
    'behavior',
    params.watcherId,
    params.dispatchSource,
    params.windowStart,
    params.windowEnd,
  ].join(':');

  const inserted = await sql`
    INSERT INTO runs (
      organization_id,
      run_type,
      watcher_id,
      approval_status,
      status,
      approved_input,
      idempotency_key,
      created_at
    ) VALUES (
      ${params.organizationId},
      'behavior',
      ${params.watcherId},
      'auto',
      'pending',
      ${sql.json(payload)},
      ${idempotencyKey},
      current_timestamp
    )
    RETURNING id, status
  `;

  const runId = Number((inserted[0] as { id: unknown }).id);
  const status = String((inserted[0] as { status: unknown }).status);

  logger.info(
    `[queue] Created watcher run ${runId} for watcher ${params.watcherId} (${params.dispatchSource})`
  );

  return { runId, status, created: true };
}

export async function createWatcherRun(
  params: {
    organizationId: string;
    watcherId: number;
    agentId: string;
    windowStart: string;
    windowEnd: string;
    dispatchSource: WatcherDispatchSource;
    deviceWorkerId?: string | null;
    agentKind?: string | null;
    sourceFingerprint?: string;
  },
  db?: DbClient
): Promise<{ runId: number; status: string; created: boolean }> {
  const sql = db ?? getDb();

  try {
    if (db) {
      return await createWatcherRunWithClient(sql, params);
    }

    return await sql.begin(async (tx) => createWatcherRunWithClient(tx, params));
  } catch (error) {
    if (isUniqueViolation(error, 'runs_idempotency_key_uniq')) {
      const idempotencyKey = [
        'behavior',
        params.watcherId,
        params.dispatchSource,
        params.windowStart,
        params.windowEnd,
      ].join(':');
      const rows = await sql`
        SELECT id, status
        FROM runs
        WHERE idempotency_key = ${idempotencyKey}
          AND status = ANY(${runStatusLiteral(ACTIVE_RUN_STATUSES)}::text[])
        LIMIT 1
      `;
      const existing = rows.length > 0
        ? { id: Number(rows[0]?.id), status: String(rows[0]?.status) }
        : null;
      if (existing) {
        logger.info(
          `[queue] Reusing concurrent watcher run ${existing.id} for watcher ${params.watcherId}`
        );
        return { runId: existing.id, status: existing.status, created: false };
      }
    }

    // Partial unique index idx_runs_pending_non_event_per_behavior:
    // one pending non-event behavior run per behavior. Manual vs scheduled
    // (different idempotency keys) still collides here under TOCTOU races.
    if (isUniqueViolation(error, 'idx_runs_pending_non_event_per_behavior')) {
      const rows = await sql`
        SELECT id, status
        FROM runs
        WHERE watcher_id = ${params.watcherId}
          AND run_type = 'behavior'
          AND watcher_id IS NOT NULL
          AND status = 'pending'
          AND COALESCE(approved_input->>'dispatch_source', 'scheduled') <> 'event'
        LIMIT 1
      `;
      const existing = rows.length > 0
        ? { id: Number(rows[0]?.id), status: String(rows[0]?.status) }
        : null;
      if (existing) {
        logger.info(
          `[queue] Reusing concurrent pending non-event watcher run ${existing.id} for watcher ${params.watcherId}`
        );
        return { runId: existing.id, status: existing.status, created: false };
      }
    }

    logger.error({ error, watcherId: params.watcherId }, '[queue] Failed to create watcher run');
    throw error;
  }
}

/** An activation that produced (or joined) a durable run. */
export interface BehaviorEventRunQueued {
  runId: number;
  status: string;
  created: boolean;
  disposition: 'queued' | 'coalesced' | 'duplicate';
}

/**
 * An activation refused by the Behavior's `min_cooldown_seconds` window. No
 * run exists, so there is no id to dispatch — the distinct shape stops callers
 * treating a suppressed activation as a queued one.
 */
export interface BehaviorEventRunSuppressed {
  runId: null;
  status: 'suppressed';
  created: false;
  disposition: 'cooldown';
}

export type BehaviorEventRunResult =
  | BehaviorEventRunQueued
  | BehaviorEventRunSuppressed;

/**
 * Durably materialize a normalized connector signal as a Behavior run. A
 * per-Behavior transaction lock makes queue/coalesce decisions replica-safe;
 * delivery_ids in historical runs provide dedupe without a webhook ledger.
 */
export async function createBehaviorEventRun(
  params: {
    organizationId: string;
    watcherId: number;
    agentId: string;
    trigger: BehaviorEventTrigger;
    signal: ConnectorTriggerSignal;
    deviceWorkerId?: string | null;
    agentKind?: string | null;
  },
  db?: DbClient
): Promise<BehaviorEventRunResult> {
  const sql = db ?? getDb();
  const execute = async (tx: DbClient): Promise<BehaviorEventRunResult> => {
    await lockBehaviorForActivation(tx, params.watcherId);

    const duplicate = await tx`
      SELECT id, status
      FROM runs
      WHERE watcher_id = ${params.watcherId}
        AND run_type = 'behavior'
        AND COALESCE(approved_input->'delivery_ids', '[]'::jsonb)
            @> ${tx.json([params.signal.delivery_id])}::jsonb
      ORDER BY created_at DESC
      LIMIT 1
    `;
    if (duplicate.length > 0) {
      return {
        runId: Number(duplicate[0]?.id),
        status: String(duplicate[0]?.status),
        created: false,
        disposition: 'duplicate',
      };
    }

    const policy = params.trigger.active_run ?? 'queue';
    const triggerKey = behaviorEventTriggerKey(params.trigger);
    const occurredAt = params.signal.occurred_at
      ? new Date(params.signal.occurred_at)
      : new Date();
    const safeOccurredAt = Number.isNaN(occurredAt.getTime())
      ? new Date()
      : occurredAt;
    const signalWindowStart = safeOccurredAt.toISOString();
    const signalWindowEnd = new Date(safeOccurredAt.getTime() + 1).toISOString();
    if (policy === 'coalesce') {
      const pending = await tx`
        SELECT id, status, approved_input
        FROM runs
        WHERE watcher_id = ${params.watcherId}
          AND run_type = 'behavior'
          AND status = 'pending'
          AND approved_input->>'dispatch_source' = 'event'
          AND approved_input->>'trigger_key' = ${triggerKey}
        ORDER BY created_at ASC
        LIMIT 1
        FOR UPDATE
      `;
      if (pending.length > 0) {
        const input = (pending[0]?.approved_input ?? {}) as WatcherRunPayload;
        const signals = input.trigger_signals ??
          (input.trigger_signal ? [input.trigger_signal] : []);
        const deliveryIds = input.delivery_ids ??
          signals.map((signal) => signal.delivery_id);
        const currentWindowStart = Date.parse(input.window_start);
        const currentWindowEnd = Date.parse(input.window_end);
        const nextInput: WatcherRunPayload = {
          ...input,
          window_start: Number.isFinite(currentWindowStart) &&
              currentWindowStart <= safeOccurredAt.getTime()
            ? input.window_start
            : signalWindowStart,
          window_end: Number.isFinite(currentWindowEnd) &&
              currentWindowEnd >= safeOccurredAt.getTime() + 1
            ? input.window_end
            : signalWindowEnd,
          trigger_signals: [...signals, params.signal],
          delivery_ids: [...deliveryIds, params.signal.delivery_id],
        };
        const merged = await tx`
          UPDATE runs
          SET approved_input = ${tx.json(nextInput)}
          WHERE id = ${pending[0]?.id}
            AND status = 'pending'
        `;
        // A zero rowcount means the run left 'pending' between the snapshot
        // and the merge (only possible for writers outside our advisory
        // lock, e.g. old pods during a rolling deploy). Fall through and
        // queue a fresh run rather than dropping the signal.
        if (merged.count > 0) {
          return {
            runId: Number(pending[0]?.id),
            status: String(pending[0]?.status),
            created: false,
            disposition: 'coalesced',
          };
        }
      }
    }

    // Only a genuinely NEW firing consumes the operator's cooldown window.
    // Everything above this line either returned an existing run (a duplicate
    // delivery) or folded the signal into one already pending (coalesce) —
    // neither starts the Behavior again, so neither should count against
    // `min_cooldown_seconds`. We hold the per-Behavior advisory lock, so the
    // read-and-consume inside this claim cannot interleave with another
    // replica handling a concurrent delivery.
    if (!(await claimBehaviorCooldown(tx, params.watcherId))) {
      return {
        runId: null,
        status: 'suppressed',
        created: false,
        disposition: 'cooldown',
      };
    }

    const versionRows = await tx`
      SELECT current_version_id
      FROM watchers
      WHERE id = ${params.watcherId}
      LIMIT 1
    `;
    const versionId = versionRows[0]?.current_version_id == null
      ? null
      : Number(versionRows[0]?.current_version_id);
    const payload: WatcherRunPayload = {
      watcher_id: params.watcherId,
      agent_id: params.agentId,
      window_start: signalWindowStart,
      window_end: signalWindowEnd,
      dispatch_source: 'event',
      version_id: versionId,
      device_worker_id: params.deviceWorkerId ?? null,
      agent_kind: params.agentKind ?? null,
      trigger_signal: params.signal,
      trigger_signals: [params.signal],
      delivery_ids: [params.signal.delivery_id],
      trigger_execution: params.trigger.execution ?? 'turn',
      trigger_output: params.trigger.output ?? 'silent',
      trigger_key: triggerKey,
    };
    const inserted = await tx`
      INSERT INTO runs (
        organization_id, run_type, watcher_id, approval_status, status,
        approved_input, idempotency_key, created_at
      ) VALUES (
        ${params.organizationId}, 'behavior', ${params.watcherId}, 'auto',
        'pending', ${tx.json(payload)},
        ${`behavior:${params.watcherId}:${params.signal.delivery_id}`},
        current_timestamp
      )
      RETURNING id, status
    `;
    return {
      runId: Number(inserted[0]?.id),
      status: String(inserted[0]?.status),
      created: true,
      disposition: 'queued',

/**
 * Trigger and reaction script action handlers for manage_behaviors:
 *   trigger, set_reaction_script
 */

import { getDb } from "../../../db/client";
import type { Env } from "../../../index";
import { isLobuGatewayRunning } from "../../../lobu/gateway";
import logger from "../../../utils/logger";
import {
  getWatcherRunInfo,
  queueAndDispatchWatcherRun,
} from "../../../watchers/automation";
import {
  compileReactionScript,
  extractReactionInputSchema,
} from "../../../watchers/reaction-executor";
import type { ToolContext } from "../../registry";
import { recordToolConfigChange } from "../helpers/config-audit";
import { requireExists } from "../helpers/db-helpers";
import type { ManageBehaviorsArgs } from "../manage_behaviors";

// ============================================
// handleTrigger
// ============================================

export async function handleTrigger(
  args: ManageBehaviorsArgs,
  _env: Env,
): Promise<{
  action: "trigger";
  behavior_id: string;
  run_id: number;
  status: string;
}> {
  const sql = getDb();

  if (!args.behavior_id) {
    throw new Error("behavior_id is required for trigger action");
  }

  if (!isLobuGatewayRunning()) {
    throw new Error("Embedded Lobu is not available.");
  }
  const dispatchResult = await queueAndDispatchWatcherRun(
    Number(args.behavior_id),
    "manual",
    sql,
  );

  if (dispatchResult.dispatch.failed > 0) {
    const failedRun = await getWatcherRunInfo(dispatchResult.runId, sql);
    throw new Error(
      failedRun?.error_message || "Failed to dispatch Behavior run.",
    );
  }

  return {
    action: "trigger",
    behavior_id: args.behavior_id,
    run_id: dispatchResult.runId,
    status: dispatchResult.status,
  };
}

// ============================================
// handleSetReactionScript
// ============================================

export async function handleSetReactionScript(
  args: ManageBehaviorsArgs,
  _env: Env,
  ctx: ToolContext,
): Promise<{
  action: "set_reaction_script";
  behavior_id: string;
  has_script: boolean;
  message: string;
}> {
  const sql = getDb();

  if (!args.behavior_id) {
    throw new Error("behavior_id is required for set_reaction_script");
  }

  await requireExists(sql, "watchers", args.behavior_id, "Behavior");

  // Reaction script is a group-shared field — every assignment in the
  // group runs the same reactions on its windows. Resolve the group once
  // and cascade across all assignments so we don't silently fork.
  const groupRows = await sql`
    SELECT watcher_group_id FROM watchers WHERE id = ${args.behavior_id} LIMIT 1
  `;
  const groupId = Number(groupRows[0].watcher_group_id);

  const script = args.reaction_script;

  if (!script || script.trim() === "") {
    await sql`
      UPDATE watchers
      SET reaction_script = NULL, reaction_script_compiled = NULL,
          reaction_input_schema = NULL
      WHERE watcher_group_id = ${groupId}
    `;
    recordToolConfigChange(ctx, {
      resourceKind: "behavior",
      resourceId: args.behavior_id,
      op: "updated",
      summary: `Behavior ${args.behavior_id} reaction script removed`,
      state: {
        id: args.behavior_id,
        watcher_group_id: groupId,
        reaction_script: null,
        reaction_input_schema: null,
      },
      changedFields: ["reaction_script"],
    });
    return {
      action: "set_reaction_script",
      behavior_id: String(args.behavior_id),
      has_script: false,
      message: "Reaction script removed.",
    };
  }

  const compiledCode = await compileReactionScript(script);
  // Derive the reaction's extraction contract from its exported `input` schema,
  // so the worker is told the exact shape the reaction will Value.Parse. NULL
  // when the reaction declares no `input` (free-form `{ summary }` fallback).
  const reactionInputSchema = await extractReactionInputSchema(script);

  await sql`
    UPDATE watchers
    SET reaction_script = ${script}, reaction_script_compiled = ${compiledCode},
        reaction_input_schema = ${reactionInputSchema ? sql.json(reactionInputSchema) : null}
    WHERE watcher_group_id = ${groupId}
  `;

  logger.info(
    `[manage_behaviors] Set reaction script for watcher ${args.behavior_id}`,
  );

  recordToolConfigChange(ctx, {
    resourceKind: "behavior",
    resourceId: args.behavior_id,
    op: "updated",
    summary: `Behavior ${args.behavior_id} reaction script updated`,
    // Snapshot of the fields just written (row not refetched); compiled code
    // is intentionally omitted to keep the state small.
    state: {
      id: args.behavior_id,
      watcher_group_id: groupId,
      reaction_script: script,
      reaction_input_schema: reactionInputSchema ?? null,
    },
    changedFields: ["reaction_script"],
  });

  return {
    action: "set_reaction_script",
    behavior_id: String(args.behavior_id),
    has_script: true,
    message:
      "Reaction script compiled and saved. It will auto-execute on future complete_window calls.",
  };
}
/**
 * POST /api/workers/me/behaviors/:behavior_id/trigger
 *
 * Manually fire a watcher run from the device that owns it. The Mac app's
 * "Run now" action posts here. Unlike the scheduled path, this:
 *   - does NOT advance `watchers.next_run_at` (manual fires shouldn't shift
 *     the cron schedule);
 *   - is idempotent against active runs — re-trigger while a previous run is
 *     pending/claimed/running returns the existing `run_id` with
 *     `already_queued: true`;
 *   - requires the calling token's bound `device_workers.id` to match
 *     `watchers.device_worker_id`. No cross-device triggering.
 *
 * Auth: same `/api/workers/*` middleware. `device_worker:run` scope (granted
 * to Mac-app PATs minted via the device-link flow).
 */

import type { Context } from 'hono';
import { getDb } from '../db/client';
import type { Env } from '../index';
import { errorMessage } from '../utils/errors';
import logger from '../utils/logger';
import { enqueueWatcherRunForWatcher } from '../watchers/automation';

export async function triggerBehaviorForDevice(c: Context<{ Bindings: Env }>) {
  const behaviorIdParam = c.req.param('behavior_id');
  if (!behaviorIdParam) {
    return c.json({ error: 'behavior_id is required' }, 400);
  }
  const watcherId = Number(behaviorIdParam);
  if (!Number.isFinite(watcherId) || watcherId <= 0) {
    return c.json({ error: 'Invalid behavior_id' }, 400);
  }

  // The middleware already verified the token has `device_worker:run` (or
  // mcp:write/admin). The trigger surface is user-scoped only — trusted
  // server workers shouldn't be triggering device-pinned watchers, that's
  // what the scheduled path is for.
  if (c.var.workerAuthMode !== 'user') {
    return c.json({ error: 'Endpoint is user-scoped only' }, 403);
  }
  const workerUserId = c.var.workerUserId;
  if (!workerUserId) {
    return c.json({ error: 'Unauthorized' }, 401);
  }
  const scopes = c.var.mcpAuthInfo?.scopes ?? [];
  if (
    !scopes.includes('device_worker:run') &&
    !scopes.includes('mcp:write') &&
    !scopes.includes('mcp:admin')
  ) {
    return c.json({ error: 'Worker token missing device_worker:run scope' }, 403);
  }

  // Resolve the caller's bound device worker. mcpAuth populates
  // `mcpAuthInfo.workerId` from the PAT row. Without a bound workerId there's
  // no way to authorize the trigger — manual fires must come from a known
  // physical device.
  const boundWorkerId = c.var.mcpAuthInfo?.workerId ?? null;
  if (!boundWorkerId) {
    return c.json({ error: 'Token is not bound to a device worker' }, 403);
  }

  const sql = getDb();
  let resolvedDeviceWorkerId: string;
  try {
    const deviceRows = (await sql`
      SELECT id, organization_id
      FROM device_workers
      WHERE user_id = ${workerUserId} AND worker_id = ${boundWorkerId}
      LIMIT 1
    `) as unknown as Array<{ id: string; organization_id: string | null }>;
    const device = deviceRows[0];
    if (!device) {
      return c.json({ error: 'Device not registered yet — poll first' }, 404);
    }
    resolvedDeviceWorkerId = device.id;
  } catch (err) {
    logger.error({ error: errorMessage(err) }, '[triggerBehaviorForDevice] device lookup failed');
    return c.json({ error: 'Internal error' }, 500);
  }

  // Load the watcher and enforce two checks:
  //   (1) the watcher is in the caller's org scope (auth middleware computed
  //       `workerOrgIds` from the token-bound org + the user's personal org);
  //   (2) `watchers.device_worker_id` matches the caller's device. Even if
  //       the user owns both devices, A cannot trigger a watcher pinned to B
  //       — that's a different pairing in the UI.
  const watcherRows = (await sql`
    SELECT id, organization_id, agent_id, status, device_worker_id::text AS device_worker_id
    FROM watchers
    WHERE id = ${watcherId}
    LIMIT 1
  `) as unknown as Array<{
    id: number;
    organization_id: string;
    agent_id: string | null;
    status: string;
    device_worker_id: string | null;
  }>;
  const watcher = watcherRows[0];
  if (!watcher) {
    return c.json({ error: 'Behavior not found' }, 404);
  }

  // Org scope: the watcher's org must be in the caller's base scope OR be a
  // cross-org pin the caller still has access to. The pin to THIS device is
  // verified next (the consent); here we just confirm membership of the
  // watcher's org for the cross-org case, mirroring the poll's membership gate.
  const orgIds = c.var.workerOrgIds ?? [];
  if (!orgIds.includes(watcher.organization_id)) {
    // workerUserId is guaranteed non-null by the guard above.
    const memberRows = (await sql`
      SELECT 1 FROM "member"
      WHERE "organizationId" = ${watcher.organization_id} AND "userId" = ${workerUserId}
      LIMIT 1
    `) as unknown as Array<unknown>;
    if (memberRows.length === 0) {
      return c.json({ error: 'Forbidden' }, 403);
    }
  }
  if (!watcher.device_worker_id || watcher.device_worker_id !== resolvedDeviceWorkerId) {
    return c.json({ error: 'Behavior is not pinned to this device' }, 403);
  }
  if ((watcher.status ?? 'active') !== 'active') {
    return c.json({ error: 'Behavior is not active' }, 409);
  }
  if (!watcher.agent_id) {
    return c.json({ error: 'Behavior has no agent assigned' }, 409);
  }

  // Enqueue (or re-use) the run. `enqueueWatcherRunForWatcher` delegates to
  // `createWatcherRun`, which checks for an active run in the same watcher_id
  // lane and reuses it (returns `created: false`). That gives us broad
  // idempotency across pending/claimed/running — re-trigger never starts a
  // second run while the first is still in flight. We intentionally do NOT
  // advance `watchers.next_run_at` here so a manual fire doesn't shift the
  // cron schedule.
  try {
    const result = await enqueueWatcherRunForWatcher(watcherId, 'manual');
    return c.json(
      {
        run_id: result.runId,
        status: result.status,
        already_queued: !result.created,
        queued_at: new Date().toISOString(),
      },
      200
    );
  } catch (err) {
    logger.error(
      { error: errorMessage(err), watcherId },
      '[triggerBehaviorForDevice] enqueue failed'
    );
    return c.json({ error: errorMessage(err) }, 500);
  }
}
  // `baseOrgScopeIds` (token's bound + personal org only) gates the UNPINNED
  // capability-matched branch, so a single pin in org B does NOT also let the
  // device claim unrelated unpinned device-connector runs in org B.
  const orgScopeIds = orgScopeActive && claimableOrgIds ? claimableOrgIds : [''];
  const baseOrgScopeIds =
    orgScopeActive && effectiveWorkerOrgIds && effectiveWorkerOrgIds.length > 0
      ? effectiveWorkerOrgIds
      : [''];

  const claimNextPendingRun = async () =>
    sql.begin(async (tx) => {
      const candidates = await tx`
      WITH next_run AS (
        SELECT r.id, r.run_type, r.watcher_id
        FROM runs r
        LEFT JOIN connections con ON con.id = r.connection_id
        -- Pin target platform: chrome-extension pins on non-chrome connectors mean
        -- browser affinity (scrape via that extension), not "run parent sync on
        -- the extension". See dispatch-chrome-action preferredBrowserWorkerForConnection.
        LEFT JOIN device_workers pin_dw ON pin_dw.id = con.device_worker_id
        LEFT JOIN LATERAL (
          SELECT cd.required_capability
          FROM connector_definitions cd
          WHERE cd.key = r.connector_key
            AND cd.organization_id = r.organization_id
            AND cd.status = 'active'
          ORDER BY cd.updated_at DESC, cd.id DESC
          LIMIT 1
        ) cd ON true
        WHERE r.status = 'pending'
          AND (r.approval_status = 'auto' OR r.approval_status = 'approved')
          AND (
            -- (1) Connector-worker lanes: sync / action / embed_backfill / auth.
            (
              r.run_type IN ('sync', 'action', 'embed_backfill', 'auth')
              AND (
                -- (1A) trusted/anonymous fleet worker: no-capability cloud
                --      connectors, any org — never a connection pinned for
                --      *execution*. Browser-affinity pins (chrome-extension on
                --      non-chrome parent syncs) still allow fleet claim.
                (
                  ${!isUserScopedWorker}
                  AND COALESCE(cd.required_capability, '') = ANY(${pgTextArray(capabilityMatchSet)}::text[])
                  -- Capability negotiation: in cloud mode, a fleet worker may
                  -- only claim a DB-egress-hardened connector run (postgres,
                  -- future warehouses) if it advertises db_egress_hardening.
                  -- Old workers that predate the hardening advertise nothing and
                  -- leave the run pending for a new worker. Empty set / non-cloud
                  -- / hardened worker => no-op. Device (user-scoped) branches
                  -- below are untouched: postgres is a fleet no-capability
                  -- connector, never a device-pinned one, so they never see it.
                  AND (
                    ${!isCloudMode()}
                    OR ${workerHardensDbEgress}
                    OR NOT (r.connector_key = ANY(${dbEgressHardenedKeys}::text[]))
                  )
                  AND (
                    con.device_worker_id IS NULL
                    OR (
                      -- Browser affinity (not job host). Exclude run_type=action:
                      -- scrape actions are always connector_key='chrome' and use
                      -- the org chrome connection pin, not LinkedIn's affinity pin.
                      pin_dw.platform = 'chrome-extension'
                      AND r.run_type IN ('sync', 'auth', 'embed_backfill')
                      AND r.connector_key NOT LIKE 'chrome%'
                    )
                  )
                )
                -- (1B) user-scoped device worker: an unpinned capability-matched
                --      device connector in an org this worker can see. Capability
                --      match goes through the authorized set — a chrome-extension
                --      claiming os.shell is dropped server-side (see
                --      @lobu/core/capabilities), and that dropped string MUST NOT
                --      match a connectors required_capability here either.
                OR (
                  ${isUserScopedWorker}
                  AND cd.required_capability IS NOT NULL
                  AND cd.required_capability = ANY(${pgTextArray(authorizedCapabilities)}::text[])
                  AND con.device_worker_id IS NULL
                  AND r.organization_id = ANY(${pgTextArray(baseOrgScopeIds)}::text[])
                )
                -- ... or any connection explicitly pinned to THIS device for
                --     *execution* (e.g. WhatsApp on Mac). Browser-affinity pins
                --     (chrome-extension + non-chrome parent sync) must NOT be
                --     claimed by the extension — those runs stay on the fleet.
                OR (
                  ${isUserScopedWorker}
                  AND ${deviceWorkerId}::uuid IS NOT NULL
                  AND con.device_worker_id = ${deviceWorkerId}::uuid
                  AND (
                    cd.required_capability IS NULL
                    OR cd.required_capability = ANY(${pgTextArray(authorizedCapabilities)}::text[])
                  )
                  AND r.organization_id = ANY(${pgTextArray(orgScopeIds)}::text[])
                  AND NOT (
                    pin_dw.platform = 'chrome-extension'
                    AND r.run_type IN ('sync', 'auth', 'embed_backfill')
                    AND r.connector_key NOT LIKE 'chrome%'
                  )
                )
              )
            )
            -- (2) Watcher lane: a watcher run with approved_input.device_worker_id
            --     matching this device. Watchers don't carry a connection_id and
            --     don't gate on capabilities — the matching device's local CLI
            --     executor handles the work (Owletto's WatcherDispatcher routes
            --     by approved_input.agent_kind). The server-side dispatcher
            --     (#802) already refuses to claim rows with this pin set, so
            --     this branch is the only legal claim path for them.
            OR (
              ${isUserScopedWorker}
              AND r.run_type = 'behavior'
              AND ${deviceWorkerId}::uuid IS NOT NULL
              AND r.approved_input ? 'device_worker_id'
              AND r.approved_input->>'device_worker_id' = ${deviceWorkerId}::text
              AND r.organization_id = ANY(${pgTextArray(orgScopeIds)}::text[])
              AND NOT EXISTS (
                SELECT 1
                FROM runs active
                WHERE active.watcher_id = r.watcher_id
                  AND active.run_type = 'behavior'
                  AND active.status IN ('claimed', 'running')
              )
            )
          )
        ORDER BY
          CASE WHEN r.run_type = 'auth' THEN 0 ELSE 1 END,
          r.created_at ASC
        FOR UPDATE OF r SKIP LOCKED
        LIMIT 1
      )
      SELECT id, run_type, watcher_id
      FROM next_run
    `;

      if (candidates.length === 0) {
        return null;
      }

      const candidate = candidates[0] as {
        id: unknown;
        run_type: unknown;
        watcher_id: unknown;
      };
      const runId = Number(candidate.id);
      if (candidate.run_type === 'behavior') {
        const claimed = await claimPendingWatcherRun(tx, {
          runId,
          watcherId: Number(candidate.watcher_id),
          claimedBy: worker_id,
          status: 'running',
        });
        if (!claimed) return null;
      } else {
        const claimed = await tx`
          UPDATE runs
          SET status = 'running',
              claimed_at = current_timestamp,
              last_heartbeat_at = current_timestamp,
              claimed_by = ${worker_id}
          WHERE id = ${runId}
            AND status = 'pending'
          RETURNING id
        `;
        if (claimed.length === 0) return null;
      }

      const rows = await tx`
      SELECT
        r.id AS run_id,
        r.run_type,
        r.feed_id,
        r.connection_id,
        r.connector_key,
        r.connector_version,
        r.action_key,
        r.action_input,
        r.approved_input,
        r.watcher_id,
        r.window_id,
        r.organization_id,
        r.created_at AS run_created_at,
        r.auth_profile_id AS run_auth_profile_id,
        f.feed_key,
        f.config AS feed_config,
        f.checkpoint,
        f.entity_ids AS feed_entity_ids,
        conn.auth_profile_id,
        conn.app_auth_profile_id,
        conn.config AS connection_config,
        conn.device_worker_id AS connection_device_worker_id,
        cv.id AS connector_version_row_id,
        cv.compiled_code,
        cv.compile_config_hash,
        cd.runtime AS connector_runtime,
        cd.required_capability AS connector_required_capability,
        ap.auth_data AS auth_profile_auth_data,
        w.name AS watcher_name,
        w.slug AS watcher_slug,
        w.agent_kind AS watcher_agent_kind,
        w.notification_channel AS watcher_notification_channel,
        w.notification_priority AS watcher_notification_priority,
        w.execution_config AS watcher_execution_config,
        wv.prompt AS watcher_prompt,
        wv.skills AS watcher_skills,
        wv.outputs AS watcher_outputs
      FROM runs r
      LEFT JOIN feeds f ON f.id = r.feed_id
      LEFT JOIN connections conn ON conn.id = r.connection_id
      LEFT JOIN LATERAL (
        SELECT id, compiled_code, compile_config_hash
        FROM connector_versions
        WHERE connector_key = r.connector_key
          AND version = r.connector_version
          AND (organization_id = r.organization_id OR organization_id IS NULL)
        ORDER BY organization_id NULLS LAST
        LIMIT 1
      ) cv ON TRUE
      LEFT JOIN connector_definitions cd ON cd.key = r.connector_key
        AND cd.organization_id = r.organization_id
        AND cd.status = 'active'
      LEFT JOIN auth_profiles ap ON ap.id = r.auth_profile_id
      LEFT JOIN watchers w ON w.id = r.watcher_id
      LEFT JOIN watcher_versions wv
        ON wv.id = COALESCE((r.approved_input->>'version_id')::bigint, w.current_version_id)
        AND wv.watcher_id = w.watcher_group_id
      WHERE r.id = ${runId}
      LIMIT 1
    `;

      return rows[0] ?? null;
    });

  let pending = await withDbRetry('worker_poll_claim', claimNextPendingRun);

  if (!pending) {
    const now = Date.now();
    if (now - lastDueFeedMaterializeAttemptAt >= DUE_FEED_MATERIALIZE_COOLDOWN_MS) {
      lastDueFeedMaterializeAttemptAt = now;

      await sql.begin(async (tx) => {
        const lockRows = await tx<{ acquired: boolean }>`
          SELECT pg_try_advisory_xact_lock(${DUE_FEEDS_LOCK_KEY}) AS acquired
        `;

        if (!lockRows[0]?.acquired) {
          return;
        }

        await materializeDueFeeds(c.env, tx);
      });

      pending = await withDbRetry('worker_poll_claim', claimNextPendingRun);
    }
