    case 'create_version':
      return `Create version for Behavior ${args.behavior_id ?? '?'}`;
    case 'set_reaction_script':
      return `Set reaction script on Behavior ${args.behavior_id ?? '?'}`;
    case 'delete':
      return `Delete Behavior(s) ${(args.behavior_ids ?? []).join(', ') || '?'}`;
