export interface DesiredWatcher {
  slug: string;
  /** Owning agent id. Every watcher belongs to exactly one agent. */
  agent: string;
  name?: string;
  description?: string;
  triggers?: DesiredBehaviorTrigger[];
  /**
   * The Behavior's task statement, authored via `defineBehavior({ prompt })`.
