export async function handleCreateFromVersion(
  args: ManageBehaviorsArgs,
  _env: Env,
  ctx: ToolContext
): Promise<{
  action: 'create_from_version';
  created: Array<{ behavior_id: string; entity_id: number; name: string }>;
}> {
  const sql = getDb();

  if (!args.version_id) throw new Error('version_id is required for create_from_version');
  if (!args.entity_ids || args.entity_ids.length === 0) {
    throw new Error('entity_ids is required for create_from_version');
  }
  // Bind the narrowed value: the transaction closure below re-widens
  // `args.entity_ids` back to `number[] | undefined`, losing this guard.
  const entityIds = args.entity_ids;

  // Fetch the source version + the source watcher's reaction script AND its
  // derived input schema. Reaction script + its `reaction_input_schema` contract
  // live on the watchers row, not on watcher_versions, so they have to be copied
  // explicitly when assigning the template to a new entity. Without this copy the
  // new assignment would have no reactions — or (dropping the input schema) a
  // reaction with no extraction contract, silently running free-form.
  const versionRows = await sql`
    SELECT wv.*, w.organization_id, w.schedule, w.timezone, w.triggers, w.sources, w.agent_id, w.scheduler_client_id,
           w.model_config, w.execution_config, w.tags, w.watcher_group_id,
           w.reaction_script, w.reaction_script_compiled, w.reaction_input_schema
    FROM watcher_versions wv
    JOIN watchers w ON w.id = wv.watcher_id
    WHERE wv.id = ${args.version_id}
    LIMIT 1
  `;
  if (versionRows.length === 0) throw new Error(`Version ${args.version_id} not found`);
  const version = versionRows[0];
  const organizationId = version.organization_id as string;
  if (!organizationId || organizationId !== ctx.organizationId) {
    throw new Error(
      `Access denied: Behavior version ${args.version_id} does not belong to your organization`
    );
  }
  if (!version.agent_id) {
    // Source watcher has no agent — cloning would silently inherit null and
    // produce active zombies the scheduler skips. Same invariant as handleCreate.
    throw new ToolUserError(
      `Source Behavior version ${args.version_id} has no agent_id; assign an agent on the source before cloning.`
    );
  }

  // The source's agent_id is copied verbatim onto every clone, and a version can
  // outlive the agent it named (agent_id has no FK, so a deleted agent leaves the
  // reference dangling). Resolve it once here so the fan-out cannot mint a whole
  // batch of Behaviors the scheduler will never run.
  await assertAgentExists(sql, organizationId, version.agent_id as string);

  // Reject cross-org entity_ids before cloning: a watcher attached to another
  // org's entity links its synced/extracted content to a non-existent in-org
  // entity (silent data-correctness bug). Names are fetched org-scoped below.
  await assertEntityIdsInOrg(sql, organizationId, entityIds);

  // Fetch entity names for name pattern substitution (org-scoped)
  const entityRows = await sql`
    SELECT e.id, e.name, et.slug AS entity_type, e.slug
    FROM entities e
    JOIN entity_types et ON et.id = e.entity_type_id
    WHERE e.organization_id = ${organizationId}
      AND e.id = ANY(${`{${entityIds.join(',')}}`}::bigint[])
  `;
  const entityMap = new Map(entityRows.map((e: any) => [Number(e.id), e]));

  // A once-valid version can outlive a referenced table or entity type. Resolve
  // its sources before fan-out, passing each assignment's entity context so
  // `{{entityId}}` is validated the same way as at runtime.
  const clonedSources = (version.version_sources ?? version.sources ?? []) as Array<{
    name: string;
    query: string;
  }>;
  const clonedOutputs = normalizeStoredJsonField(
    version.outputs,
    undefined as Record<string, unknown> | undefined
  );
  await assertOutputEntityTypesExist(sql, organizationId, clonedOutputs);
  for (const entityId of entityIds) {
    await assertOutputEventTypesExist(organizationId, clonedOutputs, [entityId]);
  }
  if (clonedSources.length > 0) {
    for (const entityId of entityIds) {
      await assertWatcherSourcesResolve(sql, organizationId, clonedSources, [entityId]);
    }
  }

  const createdBy = ctx.userId ?? 'system';
  const created: Array<{
    behavior_id: string;
    entity_id: number;
    name: string;
  }> = [];
  // Audit/lifecycle payloads are collected inside the transaction and emitted
  // only after it commits — a rollback must not leak "created" events for
  // watchers that never landed (events is append-only; we can't take them back).
  const auditPayloads: Array<{
    entityId: number;
    watcherId: number;
    watcherName: string;
    watcherSlug: string;
    sources: unknown;
    sharedVersionId: number;
    groupId: number;
  }> = [];

  // The whole fan-out runs in ONE transaction. Two reasons:
  //  1. getNextNumericId relies on pg_advisory_xact_lock, which only serializes
  //     when a real transaction is open. On the pooled autocommit connection the
  //     lock releases immediately, so concurrent assignments would both compute
  //     MAX(id)+1 and collide on the watchers PK.
  //  2. Atomicity: a mid-loop failure (e.g. a slug clash on the 3rd entity)
  //     would otherwise leave a partial fan-out — some assignments created,
  //     some not. All-or-nothing is the correct contract here.
  try {
    await sql.begin(async (tx) => {
      for (const entityId of entityIds) {
        const entity = entityMap.get(entityId);
        if (!entity) throw new Error(`Entity ${entityId} not found`);

        const namePattern = args.name_pattern ?? `${version.name}: {{entity_name}}`;
        const watcherName = namePattern.replace(/\{\{entity_name\}\}/g, entity.name as string);
        const watcherSlug = `${version.name}-${entity.slug}`
          .toLowerCase()
          .replace(/[^a-z0-9-]/g, '-');

        const watcherId = await getNextNumericId(tx, 'watchers');
        // The new assignment shares the source's existing watcher_versions row
        // rather than getting its own duplicate copy. version_id (the arg) is
        // the row in watcher_versions we're cloning from; that becomes the
        // assignment's current_version_id directly. The version row itself is
        // owned by the group root (watcher_group_id), so all assignments in
        // the group point at the same chain.
        const sharedVersionId = Number(args.version_id);
        const groupId = (version.watcher_group_id ?? version.watcher_id) as number;
        // Entity clones must not inherit chat-link steer/reply triggers (or the
        // system:chat-link tag): those bind a live channel responder, and
        // cloning them would create a second agent turn for the same message.
        const cloneTriggers = stripChatLinkTriggers(version.triggers);
        // After stripping, the residual trigger shape must still satisfy the
        // instruction rule (chat-link-only sources become manual/empty triggers
        // and require a non-empty prompt).
        // The clone SHARES the source's watcher_versions row, so its pinned
        // skills come along with it — they satisfy the rule here exactly as they
        // will at dispatch.
        assertBehaviorInstructions(
          (Array.isArray(cloneTriggers) ? cloneTriggers : []) as BehaviorTrigger[],
          version.prompt as string | null | undefined,
          version.skills as Array<{ name: string; content: string }> | null
        );
        assertBehaviorOutputsUseWindowExecution(
          (Array.isArray(cloneTriggers) ? cloneTriggers : []) as BehaviorTrigger[],
          clonedOutputs
        );
        // `tags` is a text[] column read under fetch_types:false, so postgres.js
        // hands back a raw array literal string (e.g. "{}" or "{system:chat-link}"),
        // not a JS array. Parse it before filtering.
        const cloneTags = parsePgTextArray(
          version.tags as string | string[] | null,
        ).filter((tag) => tag !== 'system:chat-link');

        await tx`
          INSERT INTO watchers (
            id, name, slug, organization_id, entity_ids,
            schedule, timezone, next_run_at, triggers, agent_id, scheduler_client_id, model_config, execution_config, sources, version,
            current_version_id, tags, status, created_by, created_at, updated_at,
            watcher_group_id, source_watcher_id,
            reaction_script, reaction_script_compiled, reaction_input_schema
          ) VALUES (
            ${watcherId}, ${watcherName}, ${watcherSlug}, ${organizationId},
            ${`{${entityId}}`}::bigint[],
            ${version.schedule ?? null}, ${version.timezone ?? null}, ${version.schedule ? nextRunAt(version.schedule as string, new Date(), version.timezone as string | null) : null}, ${toJsonParam(tx, cloneTriggers)},
            ${version.agent_id ?? null}, ${version.scheduler_client_id ?? null},
            ${toJsonParam(tx, version.model_config)}, ${toJsonParam(tx, version.execution_config)}, ${toJsonParam(tx, clonedSources)},
            ${(version.version as number) ?? 1}, ${sharedVersionId}, ${toTextArrayParam(cloneTags)}::text[],
            'active', ${createdBy}, NOW(), NOW(),
            ${groupId}, ${version.watcher_id},
            ${(version.reaction_script as string | null) ?? null},
            ${(version.reaction_script_compiled as string | null) ?? null},
            ${toJsonParam(tx, version.reaction_input_schema)}
          )
        `;

        created.push({
          behavior_id: String(watcherId),
          entity_id: entityId,
          name: watcherName,
        });
        auditPayloads.push({
          entityId,
          watcherId,
          watcherName,
          watcherSlug,
          sources: clonedSources,
          sharedVersionId,
          groupId,
        });
        // This runs inside the clone transaction, so projection failure must
        // roll the clone back with it.
        await syncBehaviorChannelFeeds({
          organizationId,
          after: Array.isArray(cloneTriggers)
            ? (cloneTriggers as BehaviorTrigger[])
            : [],
          sql: tx,
        });
      }
    });
  } catch (err) {
    // The derived slug is not pre-checked and is not locked: two concurrent
    // assignments (or a re-run) can produce the same slug and race
    // idx_watchers_org_slug. Surface a coded 409 instead of leaking a raw 23505.
    if (isUniqueViolation(err, 'idx_watchers_org_slug')) {
      throw new ToolUserError(
        `A Behavior assignment with a colliding slug already exists in this organization`,
        409
      );
    }
    throw err;
  }

  // Post-commit: emit lifecycle + audit events now that the rows are durable.
  for (const p of auditPayloads) {
    recordLifecycleEvent({
      organizationId,
      entityType: 'watcher',
      op: 'created',
      entityId: p.watcherId,
      summary: `Behavior "${p.watcherName}" created`,
      extra: { slug: p.watcherSlug, via: 'create_from_version' },
    });

    recordToolConfigChange(ctx, {
      organizationId,
      resourceKind: 'behavior',
      resourceId: p.watcherId,
      op: 'created',
      summary: `Behavior '${p.watcherName}' created from version ${args.version_id}`,
      // Composed from the cloned insert values (row not refetched); the
      // version-bound fields come from the shared source version row.
      state: {
        id: p.watcherId,
        name: p.watcherName,
        slug: p.watcherSlug,
        status: 'active',
        entity_ids: [p.entityId],
        schedule: version.schedule ?? null,
        timezone: version.timezone ?? null,
        triggers: version.triggers ?? [],
        agent_id: version.agent_id ?? null,
        scheduler_client_id: version.scheduler_client_id ?? null,
        version: (version.version as number) ?? 1,
        current_version_id: p.sharedVersionId,
        watcher_group_id: p.groupId,
        source_watcher_id: version.watcher_id,
        sources: p.sources,
        prompt: version.prompt ?? null,
        outputs: version.outputs ?? null,
        classifiers: version.classifiers ?? null,
        reactions_guidance: version.reactions_guidance ?? null,
      },
    });
  }

  return { action: 'create_from_version', created };
}
/**
 * list action handler for manage_behaviors.
 */

import {
	ListBehaviorsResultSchema,
	type ListBehaviorsArgs,
	type ListBehaviorsResult,
} from "@lobu/core/contracts/tools/manage-behaviors";
import { getDb } from "../../../db/client";
import type { Env } from "../../../index";
import logger from "../../../utils/logger";
import {
	buildBehaviorUrl,
	getOrganizationSlug,
	getPublicWebUrl,
} from "../../../utils/url-builder";
import { buildLatestWatcherRunJoinSql } from "../../../watchers/automation";
import { computeBehaviorHealth } from "../../../watchers/behavior-health";
import type { ToolContext } from "../../registry";
import { batchCountUnanalyzedContent } from "./shared";

export { ListBehaviorsResultSchema };

// ============================================
// handleList
// ============================================

export async function handleList(
	args: ListBehaviorsArgs,
	_env: Env,
	ctx: ToolContext
): Promise<ListBehaviorsResult> {
	const sql = getDb();

	if (args.entity_id) {
		const entityCheck =
			await sql`SELECT id FROM entities WHERE id = ${args.entity_id}`;
		if (entityCheck.length === 0) {
			throw new Error(`Entity with ID ${args.entity_id} not found`);
		}
	}

	let query = `
    SELECT
      i.id as behavior_id,
      i.name,
      i.slug,
      i.status,
      i.version,
      i.created_at,
      i.updated_at,
      i.triggers,
      i.next_run_at,
      i.agent_id,
      i.device_worker_id,
      i.last_fired_at,
      i.scheduler_client_id,
      i.model_config,
      i.execution_config,
      i.sources,
      -- With fetch_types:false (see db/client.ts) postgres.js does not parse
      -- arrays, so text[] arrives as the literal "{a,b}"; wrap in to_jsonb so
      -- clients get a real JSON array.
      to_jsonb(i.tags) AS tags,
      i.notification_channel,
      i.notification_priority,
      i.min_cooldown_seconds,
      i.agent_kind,
      i.watcher_group_id::text AS behavior_group_id,
      i.source_watcher_id::text AS source_behavior_id,
      wr.id as behavior_run_id,
      wr.status as behavior_run_status,
      wr.error_message as behavior_run_error,
      wr.created_at as behavior_run_created_at,
      wr.completed_at as behavior_run_completed_at,
      e.id as entity_id,
      et.slug AS entity_type,
      e.name as entity_name,
      e.slug as entity_slug,
      e.organization_id,
      parent.id as parent_id,
      parent.name as parent_name,
      parent.slug as parent_slug,
      pet.slug as parent_entity_type,
      i.current_version_id,
      (SELECT COUNT(*) FROM canvas_windows iw WHERE iw.watcher_id = i.id) as windows_count
  `;

	if (args.include_details) {
		query += `,
      cv.description,
      cv.prompt,
      cv.skills,
      cv.classifiers,
      cv.outputs,
      cv.reactions_guidance
    `;
	}

	query += `
    FROM watchers i
    LEFT JOIN entities e ON e.id = ANY(i.entity_ids)
    LEFT JOIN entity_types et ON et.id = e.entity_type_id
    LEFT JOIN entities parent ON e.parent_id = parent.id
    LEFT JOIN entity_types pet ON pet.id = parent.entity_type_id
    LEFT JOIN watcher_versions cv ON i.current_version_id = cv.id
    ${buildLatestWatcherRunJoinSql("i", "wr")}
  `;

	const conditions: string[] = [];
	const params: any[] = [];
	let paramCount = 1;

	conditions.push(`i.organization_id = $${paramCount}::text`);
	params.push(ctx.organizationId);
	paramCount++;

	if (args.entity_id) {
		conditions.push(`$${paramCount} = ANY(i.entity_ids)`);
		params.push(args.entity_id);
		paramCount++;
	}

	if (args.behavior_id) {
		conditions.push(`i.id = $${paramCount}`);
		params.push(args.behavior_id);
		paramCount++;
	}

	if (args.agent_id) {
		conditions.push(`i.agent_id = $${paramCount}`);
		params.push(args.agent_id);
		paramCount++;
	}

	if (args.status) {
		conditions.push(`i.status = $${paramCount}`);
		params.push(args.status);
		paramCount++;
	} else {
		// Default to active watchers only (exclude archived)
		conditions.push(`i.status = 'active'`);
	}

	query += ` WHERE ${conditions.join(" AND ")}`;

	const orderDir = args.order_dir === "asc" ? "ASC" : "DESC";
	if (args.order_by === "last_fired_at") {
		query += ` ORDER BY i.last_fired_at ${orderDir} NULLS LAST, i.updated_at ${orderDir}`;
	} else {
		query += ` ORDER BY i.created_at ${orderDir}`;
	}

	if (args.limit != null && args.limit > 0) {
		query += ` LIMIT $${paramCount}`;
		params.push(args.limit);
		paramCount++;
	}

	const result = await sql.unsafe(query, params);

	const baseUrl = getPublicWebUrl(ctx.requestUrl, ctx.baseUrl);
	const watcherIds = (result as any[]).map((i) => Number(i.behavior_id));

	let counts: Map<number, { pending: number; historical: number }>;
	try {
		counts = await batchCountUnanalyzedContent(watcherIds);
	} catch (error) {
		logger.error(
			{ error },
			"[manage_behaviors] Error batch counting unanalyzed content"
		);
		counts = new Map();
	}

	const uniqueOrgIds = [
		...new Set(
			(result as any[]).map((r) => r.organization_id as string).filter(Boolean)
		),
	];
	const orgSlugMap = new Map<string, string>();
	for (const orgId of uniqueOrgIds) {
		const slug = await getOrganizationSlug(orgId);
		if (slug) orgSlugMap.set(orgId, slug);
	}

	const watchersWithPendingCount = (result as any[]).map((watcher) => {
		const watcherId = Number(watcher.behavior_id);
		const countData = counts.get(watcherId) || { pending: 0, historical: 0 };
		const orgSlug = orgSlugMap.get(watcher.organization_id as string) ?? null;

		const viewUrl =
			orgSlug && watcher.agent_id
				? buildBehaviorUrl(orgSlug, watcher.agent_id, watcherId, baseUrl)
				: undefined;

		const { organization_id: _orgId, ...rest } = watcher;

		// Old persisted run-error rows can carry the internal `client.watchers.*`
		// namespace (the SDK alias was renamed watchers→behaviors; forward-path
		// templates already emit `client.behaviors.*`, but archived error_message
		// rows still hold the legacy string). Rewrite it at read time so the
		// public projection never surfaces the internal vocabulary.
		if (typeof (rest as Record<string, unknown>).behavior_run_error === "string") {
			(rest as Record<string, unknown>).behavior_run_error = (
				(rest as Record<string, unknown>).behavior_run_error as string
			).replaceAll("client.watchers.", "client.behaviors.");
		}

		if (!args.include_details) {
			delete (rest as Record<string, unknown>).prompt;
			delete (rest as Record<string, unknown>).skills;
			delete (rest as Record<string, unknown>).classifiers;
			delete (rest as Record<string, unknown>).description;
		}

		// Stringify `behavior_id` to match the rest of the manage_behaviors
		// contract: `handleCreate` returns `String(watcherId)`, the input schema
		// declares `behavior_id` as a string, and downstream callers (CLI
		// `apply-cmd.ts` → `updateWatcher`, MCP tools) forward whatever they
		// receive straight back. Without the cast the raw integer leaks through
		// and a follow-up `update`/`upgrade` call fails the schema gate with
		// `/behavior_id: Expected string`. Same bug pattern for `current_version_id`
		// (kept as-is — no consumer feeds it back into manage_behaviors today).
		if ((rest as Record<string, unknown>).behavior_id != null) {
			(rest as Record<string, unknown>).behavior_id = String(
				(rest as Record<string, unknown>).behavior_id
			);
		}

		// Computed health (item 3, #2033) — derived from the
		// already-selected schedule/run columns, no extra query.
		const behaviorHealth = computeBehaviorHealth({
			status: watcher.status,
			nextRunAt: watcher.next_run_at,
			latestRunStatus: watcher.behavior_run_status,
			latestRunCreatedAt: watcher.behavior_run_created_at,
			// Use the vocab-rewritten error so last_scheduling_error also carries the
			// public `client.behaviors.*` namespace, not the legacy internal one.
			latestRunError: (rest as Record<string, unknown>).behavior_run_error as
				| string
				| null
				| undefined,
		});

		return {
			...rest,
			organization_slug: orgSlug,
			pending_content_count: countData.pending,
			historical_content_count: countData.historical,
			view_url: viewUrl,
			health: behaviorHealth.health,
			...(behaviorHealth.reasons.length > 0 && {
				health_reasons: behaviorHealth.reasons,
			}),
			last_scheduling_error: behaviorHealth.last_scheduling_error,
		};
	});

	return { action: "list", behaviors: watchersWithPendingCount };
}

    }
  }
}

// ============================================
// Batch content counting
// ============================================

import { entityLinkMatchSql } from '../../../utils/content-search';
import { getErrorMessage } from '@lobu/core';

/**
 * Batch count unanalyzed content for multiple watchers in a single query.
 * Returns a map of watcher_id -> count of content not yet in any window for that watcher.
 */
export async function batchCountUnanalyzedContent(
  watcherIds: number[]
): Promise<Map<number, { pending: number; historical: number }>> {
  if (watcherIds.length === 0) {
    return new Map();
  }

  const sql = getDb();

  const placeholders = watcherIds.map((_, i) => `$${i + 1}`).join(', ');

  // The "total content" count joins current_event_records on the entity link
  // for every watcher in the result. On high-volume entities this scans
  // 100K+ rows per Behavior and dominates list latency (8-12s on
  // prod for orgs with even a single Reddit-Digest-class watcher).
  //
  // Cap the per-watcher total at TOTAL_CAP rows. The badge derived from
  // `pending_count = total - analyzed` becomes "TOTAL_CAP+ - analyzed"
  // semantics above the cap; the only consumer is a list-row badge that
  // doesn't need exact counts above a threshold.
  const TOTAL_CAP = 1000;
  const result = await sql.unsafe(
    `
    WITH watcher_entities AS (
      SELECT i.id as watcher_id, unnest(i.entity_ids) as entity_id
      FROM watchers i
      WHERE i.id IN (${placeholders})
        AND array_length(i.entity_ids, 1) > 0
    ),
    analyzed_counts AS (
      -- Canvas-on-events: window_id link rows carry a denormalized watcher_id, so
      -- count analyzed events directly off watcher_window_events without a join
      -- through the retired watcher_windows table.
      SELECT
        ie.watcher_id,
        COUNT(DISTINCT iwc.event_id) as analyzed_count
      FROM (SELECT DISTINCT watcher_id FROM watcher_entities) ie
      LEFT JOIN watcher_window_events iwc ON iwc.watcher_id = ie.watcher_id
      GROUP BY ie.watcher_id
    ),
    total_counts AS (
      SELECT
        wid AS watcher_id,
        (SELECT COUNT(*) FROM (
          SELECT 1 FROM watcher_entities ie
          JOIN current_event_records f ON ${entityLinkMatchSql('ie.entity_id::bigint', 'f')}
          WHERE ie.watcher_id = wid
          LIMIT ${TOTAL_CAP}
        ) capped) AS total_count
      FROM (SELECT DISTINCT watcher_id AS wid FROM watcher_entities) per_watcher
    )
    SELECT
      ac.watcher_id,
      CAST(GREATEST(COALESCE(tc.total_count, 0) - COALESCE(ac.analyzed_count, 0), 0) AS INTEGER) as pending_count,
      0 as historical_count
    FROM analyzed_counts ac
    LEFT JOIN total_counts tc ON tc.watcher_id = ac.watcher_id
    `,
    watcherIds
  );

  const counts = new Map<number, { pending: number; historical: number }>();
  for (const row of result) {
    counts.set(Number(row.watcher_id), {
      pending: (row.pending_count as number) ?? 0,
      historical: (row.historical_count as number) ?? 0,
    });
  }

  for (const id of watcherIds) {
    if (!counts.has(id)) {
      counts.set(id, { pending: 0, historical: 0 });
    }
  }

  return counts;
}
